#nullable enable

using Alba;
using JasperFx.Events;      // BuildEvent / WithTag — the tagged-GIVEN helper below
using Marten;
using Spend.Concurrency;    // DepartmentTag
using Spend.Contracts;
using Spend.Slices.Spend;
using Shouldly;
using Xunit;

namespace Spend.IntegrationTests.Slices.Spend;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: state-change. Status: ready.
///
/// **These are the SEQUENTIAL scenarios, and that is their limit.** Every one of them appends its GIVEN and
/// sends one command, so all four pass against a decider with no concurrency guard at all — including
/// gwt-commit-2, the cross-stream rejection. That is not a defect in them; it is what a GWT is. The race is
/// asserted in Concurrency/CrossAggregateRaceTests, and the control there proves these four cannot see it.
/// </summary>
public sealed class CommitSpendTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly Guid Department = SeedData.DepartmentId;
    private static readonly Guid ProjectA = Guid.Parse("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");
    private static readonly Guid ProjectB = Guid.Parse("bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb");

    private async Task GivenABudgetOf(decimal budget)
    {
        await Given(Department, new DepartmentBudgetSet(Department, budget));
        await Given(ProjectA, new ProjectOpened(ProjectA, Department, "Rewire the hall"));
        await Given(ProjectB, new ProjectOpened(ProjectB, Department, "Repaint the foyer"));
    }

    /// <summary>
    /// A GIVEN THAT THE DCB BOUNDARY CAN SEE — and needing this at all is a real cost of choosing DCB,
    /// found by a test failing rather than by reading the docs.
    ///
    /// <c>IntegrationContext.Given</c> appends straight to the stream, which is exactly right for a GWT:
    /// history is what a GIVEN means. But a DCB boundary is folded from a TAG QUERY, and an event appended
    /// without the tag is not in it. So a raw GIVEN of a prior commitment leaves the boundary reading zero,
    /// and the decider cheerfully allows spending that should have been refused.
    ///
    /// **THREE OF THE FOUR TESTS IN THIS FILE PASSED FOR THE WRONG REASON BEFORE THIS EXISTED.** Only the
    /// rejection caught it — the two "this is allowed" cases were allowed because the boundary saw nothing,
    /// which is the same green as being allowed correctly. That is the whole hazard of a positive test.
    ///
    /// The general rule: <b>once a slice decides on a tag boundary, its GIVENs must be tagged too, or they
    /// are not that slice's history.</b> Nothing in the kit enforces this and nothing can — the compiler
    /// sees a perfectly good append.
    /// </summary>
    private async Task GivenTagged(Guid stream, params object[] events)
    {
        await using var session = Store.LightweightSession();
        foreach (var body in events)
        {
            var e = session.Events.BuildEvent(body);
            e.WithTag(new DepartmentTag(Department));
            session.Events.Append(stream, e);
        }
        await session.SaveChangesAsync();
    }

    private Task<(Wolverine.Tracking.ITrackedSession, IScenarioResult)> Commit(
        Guid project, decimal amount, int expect) =>
        WhenPosting(_ =>
        {
            // Alba's status assertions hang off the SCENARIO, not off the send expression — chaining
            // .StatusCodeShouldBe onto .ToUrl() is CS1061, which reads like a missing using.
            _.Post.Json(new CommitSpend(project, Department, amount))
                .ToUrl($"/projects/{project}/commit");
            _.StatusCodeShouldBe(expect);
        });

    // Spend within the department's remaining budget is committed
    //   GIVEN Department Budget Set(budget=100000)
    //   WHEN  CommitSpend(amount=40000)
    //   THEN  Spend Committed(amount=40000)
    [Fact]
    public async Task SpendWithinTheDepartmentSRemainingBudgetIsCommitted()
    {
        await GivenABudgetOf(100_000m);

        await Commit(ProjectA, 40_000m, 204);

        var events = await EventsFor(ProjectA);
        events[^1].ShouldBeOfType<SpendCommitted>().Amount.ShouldBe(40_000m);
    }

    // Spend in another project of the same department counts against the budget
    //   GIVEN Spend Committed(projectId=$ProjectB, amount=70000)
    //   WHEN  CommitSpend(projectId=$ProjectA, amount=40000)
    //   THEN  error: DepartmentBudgetExceeded
    [Fact]
    public async Task SpendInAnotherProjectOfTheSameDepartmentCountsAgainstTheBudget()
    {
        await GivenABudgetOf(100_000m);

        // THE GIVEN IS IN A STREAM THE COMMAND DOES NOT WRITE. That single line is what makes this rule
        // cross-stream, and it is why the decider folds the department tag rather than this project.
        await GivenTagged(ProjectB, new SpendCommitted(ProjectB, Department, 70_000m));

        var (_, result) = await Commit(ProjectA, 40_000m, 400);
        result.ReadAsText().ShouldContain(CommitSpendEndpoint.BudgetExceeded);

        // 70k + 40k > 100k, so nothing may be appended to A.
        (await EventsFor(ProjectA)).ShouldNotContain(e => e is SpendCommitted);
    }

    // Committing exactly the remaining budget is allowed
    //   GIVEN Spend Committed(amount=60000)
    //   WHEN  CommitSpend(amount=40000)
    //   THEN  Spend Committed(amount=40000)
    [Fact]
    public async Task CommittingExactlyTheRemainingBudgetIsAllowed()
    {
        await GivenABudgetOf(100_000m);
        await GivenTagged(ProjectB, new SpendCommitted(ProjectB, Department, 60_000m));

        // THE BOUNDARY CASE, and the reason the rule is `>` and not `>=`. Exactly spending the budget is
        // allowed; a model that got this backwards would pass every other test here.
        await Commit(ProjectA, 40_000m, 204);

        (await EventsFor(ProjectA)).ShouldContain(e => e is SpendCommitted);
    }

    // A release frees the budget for a later commitment
    //   GIVEN Commitment Released(amount=70000)
    //   WHEN  CommitSpend(amount=40000)
    //   THEN  Spend Committed(amount=40000)
    [Fact]
    public async Task AReleaseFreesTheBudgetForALaterCommitment()
    {
        await GivenABudgetOf(100_000m);

        // Committed then released, in ANOTHER project: the department is back to nothing committed, so the
        // 40k fits. This is the test that would fail if the boundary fold ignored releases — and it would
        // fail nowhere else, because every other scenario only ever adds.
        await GivenTagged(ProjectB,
            new SpendCommitted(ProjectB, Department, 70_000m),
            new CommitmentReleased(ProjectB, Department, 70_000m));

        await Commit(ProjectA, 40_000m, 204);

        (await EventsFor(ProjectA)).ShouldContain(e => e is SpendCommitted);
    }
}
